import os
s3_client = S3Client()

while True:
    try:
        task = queue_in.get(timeout=1)
        if task is None:
            queue_out.put(None)
            return
        index, paths = task
    except Queue.Empty:
        continue

    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)

    missing_files = []

    for path in paths:
        file_path = os.path.join(cache_dir, path)
        if not os.path.exists(file_path) or not os.path.isfile(file_path):
            missing_files.append(path)

    if not missing_files:
        queue_out.put(index)
        continue

    try:
        for path in missing_files:
            file_path = os.path.join(cache_dir, path)
            s3_client.download_file(input_dir['s3_bucket'], path, file_path)
        queue_out.put(index)
    except ClientError as e:
        print(f"Error downloading file {path}: {e}")
        queue_out.put(None)

