def extract_node_strategy(node_config: dict) -> dict:
    """
    Extracts the node strategy from the given node configuration.

    :param node_config: dict, The node configuration from which the strategy is to be extracted.
    :return: dict, The extracted node strategy.
    """
    strategy = node_config.get('strategy')
    if strategy is None:
        return {}

    if 'type' not in strategy:
        return {}

    strategy_type = strategy['type']
    strategy_params = strategy.get('params', {})

    return {
        'type': strategy_type,
        'params': strategy_params
    }


def extract_node_strategies(config_dict: dict) -> dict:
    """
    Extracts the node strategies from the given configuration dictionary.

    :param config_dict: dict, The configuration dictionary from which the node strategies are to be extracted.
    :return: dict, The extracted node strategies.
    """
    node_strategies = {}
    for node_line_name, node_line in config_dict.get('node_lines', []):
        for node_name, node_config in node_line.get('nodes', {}).items():
            node_strategy = extract_node_strategy(node_config)
            if node_strategy:
                node_strategies[node_name] = node_strategy

    return node_strategies


